            }
        } else {
            nar.update(&chunk);
        }
    }
    if is_zst {
        let tail = zstd
            .finish()
            .inspect_err(|failure| {
                log::event(
                    "warn",
                    "write.nar_measure_failed",
                    &[
                        ("phase", "finish".to_string()),
                        ("error", format!("{failure:?}")),
                        ("compressedBytesRead", compressed.byte_count().to_string()),
                        ("decodedBytes", zstd.decompressed_bytes().to_string()),
