async fn measure_stored_nar(
    bucket: &worker::Bucket,
    key: &NarKey,
    declared_nar_bytes: u64,
) -> std::result::Result<NarFacts, ClientError> {
    let Some(object) = bucket
        .get(key.as_str())
        .execute()
        .await
        .map_err(|_| ClientError::StorageUnavailable)?
