    let cache_key = generation.map(probe_inventory_cache_key);
    if let Some(cache_key) = &cache_key {
        if let Some(mut hit) = Cache::default().get(cache_key, true).await? {
            if let Ok(text) = hit.text().await {
                if let Ok(held) = serde_json::from_str::<BTreeSet<String>>(&text) {
                    return Ok(Ok((held, 0)));
                }
            }
            // A memo that will not parse is the worker's own writing gone
            // wrong; enumerating is always available, so fall through
            // rather than refusing a push over a cache entry.
            log::event("warn", "probe.inventory_corrupt", &[]);
        }
    }

    let bucket = env.bucket("CACHE_BUCKET")?;
    // why: the delimiter collapses `nar/` into a common prefix, so the
    // enumeration prices root-level objects — narinfos — rather than the
    // NAR objects that would double every page.
    let mut held: BTreeSet<String> = BTreeSet::new();
    let mut cursor: Option<String> = None;
    let mut pages: u64 = 0;
    loop {
        let mut builder = bucket.list().delimiter("/").limit(
            u32::try_from(cachet_core::constants::BUCKET_LIST_PAGE_LIMIT)
                .expect("the page limit fits u32"),
        );
        if let Some(cursor) = &cursor {
            builder = builder.cursor(cursor);
        }
        let listed = match builder.execute().await {
            Ok(listed) => listed,
            Err(failure) => {
                log::event(
                    "error",
                    "probe.list_failed",
                    &[("error", failure.to_string())],
                );
                return Ok(Err(ClientError::StorageUnavailable));
            }
        };
        pages += 1;
        for object in listed.objects() {
            if let Some(hash) = object.key().strip_suffix(NARINFO_KEY_SUFFIX) {
                held.insert(hash.to_string());
            }
        }
        if !listed.truncated() {
            break;
        }
        cursor = listed.cursor();
    }

    if let Some(cache_key) = cache_key {
        if let Ok(text) = serde_json::to_string(&held) {
            ctx.wait_until(async move {
                let headers = worker::Headers::new();
                if headers.set("content-type", "application/json").is_err() {
                    return;
                }
                // The Cache API drops a response with no positive
                // max-age, so the lifetime is stated rather than implied.
                if headers
                    .set(
                        "cache-control",
                        &format!("public, max-age={PROBE_INVENTORY_TTL_SECONDS}"),
                    )
                    .is_err()
                {
                    return;
                }
                if let Ok(response) = Response::ok(text) {
                    let _ = Cache::default()
                        .put(cache_key, response.with_headers(headers))
                        .await;
                }
            });
        }
    }
    Ok(Ok((held, pages)))
}
